import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.E8pQZ6KS.js";const c=JSON.parse('{"title":"就业与认证","description":"","frontmatter":{},"headers":[],"relativePath":"竞赛与成长/就业与认证.md","filePath":"竞赛与成长/就业与认证.md","lastUpdated":1792430298000}'),l={name:"竞赛与成长/就业与认证.md"};function o(i,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="就业与认证" tabindex="-1">就业与认证 <a class="header-anchor" href="#就业与认证" aria-label="Permalink to &quot;就业与认证&quot;">​</a></h1><blockquote><p>网安人才缺口巨大，岗位方向多元。本文汇总主流岗位与证书信息，具体招聘要求以企业发布为准。</p></blockquote><h2 id="岗位方向" tabindex="-1">岗位方向 <a class="header-anchor" href="#岗位方向" aria-label="Permalink to &quot;岗位方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>岗位举例</th><th>核心能力</th></tr></thead><tbody><tr><td>攻防实战</td><td>渗透测试工程师、红队/蓝队</td><td>网络攻防、Web 安全、漏洞利用</td></tr><tr><td>安全运营</td><td>安全运维、安全运营中心（SOC）分析师、应急响应</td><td>系统加固、日志分析、事件处置</td></tr><tr><td>安全研发</td><td>安全产品研发、检测引擎开发</td><td>编程 + 安全知识（Web/二进制）</td></tr><tr><td>安全研究</td><td>漏洞研究、威胁情报、逆向分析</td><td>二进制、逆向、恶意代码</td></tr><tr><td>合规咨询</td><td>等保测评、数据合规、安全咨询</td><td>法律法规 + 标准体系</td></tr><tr><td>新兴方向</td><td>云安全、AI 安全、车联网/IoT 安全</td><td>对应技术栈（见 <a href="./../安全方向/物联网与云安全.html">物联网与云安全</a> 等）</td></tr></tbody></table><h2 id="常见认证" tabindex="-1">常见认证 <a class="header-anchor" href="#常见认证" aria-label="Permalink to &quot;常见认证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>CISP（注册信息安全专业人员）</td><td>国内认可度高的从业认证，适合就业后考取</td></tr><tr><td>NISP（国家信息安全水平考试）</td><td>面向在校生的信息安全认证，分级考试</td></tr><tr><td>OSCP</td><td>国际知名渗透测试实战认证，含金量高、考取难度大</td></tr><tr><td>CISSP</td><td>资深安全从业者认证，偏管理/体系，需工作经验</td></tr><tr><td>等保测评师 / 云安全相关认证</td><td>对应具体岗位方向</td></tr></tbody></table><p>::: note 认证信息会随政策变化，请以官方机构最新公告为准；在校期间以技术实战为主，认证多在求职前后按需考取。 :::</p><h2 id="简历与求职建议" tabindex="-1">简历与求职建议 <a class="header-anchor" href="#简历与求职建议" aria-label="Permalink to &quot;简历与求职建议&quot;">​</a></h2><ul><li><strong>用作品说话</strong>：CTF 奖项、GitHub 安全项目（Writeup 仓库、自研工具）、实习经历，是网安简历的三大支柱；</li><li><strong>实习前置</strong>：大二暑期起争取安全公司/政企安全部门实习（实习僧、牛客、公司官网/公众号等渠道）；</li><li><strong>校招节点</strong>：秋招（大四上 9-11 月）与春招（大四下 3-5 月），安全大厂（奇安信、深信服、绿盟、天融信等）与综合大厂安全团队均可关注；</li><li>善用校园渠道：学院就业信息、校园招聘会、老师与学长内推。</li></ul><h2 id="长期视角" tabindex="-1">长期视角 <a class="header-anchor" href="#长期视角" aria-label="Permalink to &quot;长期视角&quot;">​</a></h2><ul><li>安全行业技术迭代快，<strong>持续学习能力比当前水平更重要</strong>；</li><li>深耕一个方向建立标签（如「Web 渗透」「二进制漏洞」），再横向扩展；</li><li>遵守职业道德与法律（见 <a href="./../安全方向/法律伦理与合规.html">法律伦理与合规</a>），口碑是安全人最宝贵的资产。</li></ul>',11)])])}const u=d(l,[["render",o]]);export{c as __pageData,u as default};
